/**
 * Route synchronization test.
 *
 * Verifies that the authoritative route registry (src/lib/routes.ts) stays
 * in sync with:
 *   1. The React Router route definitions in src/App.tsx
 *   2. The Cloudflare Pages Function edge routing (functions/_middleware.ts)
 *   3. The static redirect files generated by scripts/generate-static-routing.mjs
 *
 * This prevents:
 *   - Application page routes missing from edge valid routes (→ accidental 404)
 *   - Legacy redirects missing from edge (→ accidental 200 soft-404)
 *   - Stale routes remaining in edge valid routes
 *   - Redirects incorrectly classified as valid pages
 *
 * Run: bunx vitest run src/test/route-sync.test.ts
 */

import { describe, it, expect } from "vitest";
import { readFileSync, existsSync } from "fs";
import { join } from "path";

// Authoritative source
import {
  validPageRoutes,
  noIndexRoutes,
  dynamicRoutePrefixes,
  homepageAliases,
  legacyRedirects,
  resolveLegacyRedirect,
  isValidPageRoute,
} from "@/lib/routes";

// ─── Parse App.tsx route definitions ───
function parseAppRoutes(): { pages: string[]; redirects: string[] } {
  const appPath = join(process.cwd(), "src", "App.tsx");
  const content = readFileSync(appPath, "utf-8");

  const pages: string[] = [];
  const redirects: string[] = [];

  // Match: <Route path="/some/path" element={<Component />} />
  const routeRegex = /path=["']([^"']+)["']/g;
  let match: RegExpExecArray | null;

  while ((match = routeRegex.exec(content)) !== null) {
    const p = match[1];
    if (p === "/" || p === "*") continue; // skip catch-all
    if (p.includes(":")) {
      // Dynamic route — extract prefix
      const prefix = p.split(":")[0];
      redirects.push(prefix.replace(/\/$/, ""));
    } else {
      pages.push(p);
    }
  }

  return { pages, redirects };
}

// ─── Parse functions/_middleware.ts route data ───
function parseEdgeRoutes(): {
  pages: string[];
  noIndex: string[];
  dynamicPrefixes: string[];
  aliases: string[];
  redirects: Record<string, string>;
} {
  const edgePath = join(process.cwd(), "functions", "_middleware.ts");
  if (!existsSync(edgePath)) {
    return {
      pages: [],
      noIndex: [],
      dynamicPrefixes: [],
      aliases: [],
      redirects: {},
    };
  }
  const content = readFileSync(edgePath, "utf-8");

  function extractArray(varName: string): string[] {
    const regex = new RegExp(`const ${varName}[^=]*=\\s*\\[([^\\]]+)\\]`, "s");
    const m = content.match(regex);
    if (!m) return [];
    return (m[1].match(/["']([^"']+)["']/g) || []).map((s) =>
      s.replace(/["']/g, ""),
    );
  }

  function extractRecord(varName: string): Record<string, string> {
    const regex = new RegExp(
      `const ${varName}[^=]*:\\s*Record<string, string>\\s*=\\s*\\{([^}]+)\\}`,
      "s",
    );
    const m = content.match(regex);
    if (!m) return {};
    const result: Record<string, string> = {};
    const entryRegex = /["']([^"']+)["']\s*:\s*["']([^"']+)["']/g;
    let em: RegExpExecArray | null;
    while ((em = entryRegex.exec(m[1])) !== null) {
      result[em[1]] = em[2];
    }
    return result;
  }

  return {
    pages: extractArray("validPageRoutes"),
    noIndex: extractArray("noIndexRoutes"),
    dynamicPrefixes: extractArray("dynamicRoutePrefixes"),
    aliases: extractArray("homepageAliases"),
    redirects: extractRecord("legacyRedirects"),
  };
}

// ─── Check static redirect files exist ───
function staticRedirectFilesExist(): { exist: string[]; missing: string[] } {
  const publicDir = join(process.cwd(), "public");
  const exist: string[] = [];
  const missing: string[] = [];

  for (const src of Object.keys(legacyRedirects)) {
    let filePath: string;
    if (src.endsWith(".html")) {
      filePath = join(publicDir, src);
    } else if (src.endsWith("/")) {
      filePath = join(publicDir, src.replace(/\/+$/, ""), "index.html");
    } else {
      filePath = join(publicDir, src, "index.html");
    }
    if (existsSync(filePath)) {
      exist.push(src);
    } else {
      missing.push(src);
    }
  }

  // 404.html
  if (existsSync(join(publicDir, "404.html"))) {
    exist.push("404.html");
  } else {
    missing.push("404.html");
  }

  return { exist, missing };
}

describe("Route Registry — Authoritative Source", () => {
  it("validPageRoutes contains the homepage", () => {
    expect(validPageRoutes).toContain("/");
  });

  it("validPageRoutes are all unique", () => {
    expect(new Set(validPageRoutes).size).toBe(validPageRoutes.length);
  });

  it("noIndexRoutes are not also in validPageRoutes", () => {
    for (const r of noIndexRoutes) {
      expect(validPageRoutes).not.toContain(r);
    }
  });

  it("legacyRedirects keys are not in validPageRoutes (no overlap, except trailing-slash normalization)", () => {
    for (const key of Object.keys(legacyRedirects)) {
      const normalized = key.replace(/\/+$/, "") || "/";
      const dest = legacyRedirects[key];
      // Trailing-slash variants (e.g. "/mission-foundation/" → "/mission-foundation")
      // are legitimate normalization redirects TO a valid page. Skip these.
      if (key.endsWith("/") && dest === normalized) continue;
      expect(validPageRoutes).not.toContain(normalized);
    }
  });

  it("homepageAliases are not in validPageRoutes", () => {
    for (const alias of homepageAliases) {
      const normalized = alias.replace(/\/+$/, "") || "/";
      expect(validPageRoutes).not.toContain(normalized);
    }
  });

  it("resolveLegacyRedirect returns correct destinations", () => {
    expect(resolveLegacyRedirect("/technology")).toBe("/services/technology");
    expect(resolveLegacyRedirect("/blog")).toBe("/insights");
    expect(resolveLegacyRedirect("/blog/some-slug")).toBe(
      "/insights/some-slug",
    );
    expect(resolveLegacyRedirect("/operations")).toBe("/services/operations");
    expect(resolveLegacyRedirect("/home")).toBe("/");
    expect(resolveLegacyRedirect("/index.html")).toBe("/");
    expect(resolveLegacyRedirect("/nonexistent-xyz")).toBeNull();
  });

  it("isValidPageRoute correctly identifies valid routes", () => {
    expect(isValidPageRoute("/")).toBe(true);
    expect(isValidPageRoute("/services/operations")).toBe(true);
    expect(isValidPageRoute("/insights/some-article")).toBe(true);
    expect(isValidPageRoute("/analytics-dashboard")).toBe(true);
    expect(isValidPageRoute("/nonexistent-xyz")).toBe(false);
    expect(isValidPageRoute("/technology")).toBe(false); // it's a redirect, not valid
  });
});

describe("Route Sync — App.tsx ↔ routes.ts", () => {
  const { pages: appPages } = parseAppRoutes();

  it("every static App.tsx route is in validPageRoutes or noIndexRoutes", () => {
    const allValid = [...validPageRoutes, ...noIndexRoutes];
    for (const p of appPages) {
      // Skip routes that are intentionally redirects (handled by legacyRedirects)
      const isRedirect = resolveLegacyRedirect(p) !== null;
      if (isRedirect) continue;
      expect(allValid).toContain(p);
    }
  });

  it("every validPageRoute (non-dynamic) has a corresponding App.tsx route", () => {
    for (const r of validPageRoutes) {
      if (r === "/") continue;
      // The route should appear in App.tsx
      const appPath = join(process.cwd(), "src", "App.tsx");
      const content = readFileSync(appPath, "utf-8");
      expect(content).toContain(`path="${r}"`);
    }
  });
});

describe("Route Sync — Edge Function ↔ routes.ts", () => {
  const edge = parseEdgeRoutes();

  it("edge validPageRoutes matches routes.ts", () => {
    expect(edge.pages.sort()).toEqual([...validPageRoutes].sort());
  });

  it("edge noIndexRoutes matches routes.ts", () => {
    expect(edge.noIndex.sort()).toEqual([...noIndexRoutes].sort());
  });

  it("edge dynamicRoutePrefixes matches routes.ts", () => {
    expect(edge.dynamicPrefixes.sort()).toEqual(
      [...dynamicRoutePrefixes].sort(),
    );
  });

  it("edge homepageAliases matches routes.ts", () => {
    expect(edge.aliases.sort()).toEqual([...homepageAliases].sort());
  });

  it("edge legacyRedirects matches routes.ts", () => {
    expect(edge.redirects).toEqual(legacyRedirects);
  });
});

describe("Route Sync — Deployed Cloudflare Worker source", () => {
  const source = readFileSync(join(process.cwd(), "cloudflare", "edge-routing-worker.js"), "utf-8");
  const extractArray = (name: string): string[] => {
    const match = source.match(new RegExp(`const ${name}\\s*=\\s*\\[([^\\]]+)\\]`, "s"));
    return (match?.[1].match(/["']([^"']+)["']/g) ?? []).map((v) => v.slice(1, -1));
  };
  const extractRedirects = (): Record<string, string> => {
    const body = source.match(/const legacyRedirects = \{([\s\S]*?)\n\};/)?.[1] ?? "";
    const entries = [...body.matchAll(/["']([^"']+)["']\s*:\s*["']([^"']+)["']/g)];
    return Object.fromEntries(entries.map(([, key, value]) => [key, value]));
  };

  it("Worker public routes stay in sync with the application", () => {
    expect(extractArray("validPageRoutes")).toEqual(validPageRoutes);
    expect(extractArray("noIndexRoutes")).toEqual(noIndexRoutes);
    expect(extractArray("dynamicRoutePrefixes")).toEqual(dynamicRoutePrefixes);
    expect(extractArray("homepageAliases")).toEqual(homepageAliases);
    expect(extractRedirects()).toEqual(legacyRedirects);
  });

  it("Worker preserves hosting endpoints and non-page HTTP methods", () => {
    expect(source).toContain('request.method !== "GET" && request.method !== "HEAD"');
    for (const prefix of ["/__vibe/", "/cdn-cgi/", "/.well-known/"]) {
      expect(source).toContain(prefix);
    }
  });
});

describe("Route Sync — Static redirect files exist", () => {
  it("all legacy redirect static files have been generated", () => {
    const { missing } = staticRedirectFilesExist();
    if (missing.length > 0) {
      console.warn(
        `⚠️  Missing static redirect files: ${missing.join(", ")}\n` +
          `Run: node scripts/generate-static-routing.mjs`,
      );
    }
    // Warn but don't fail — static files are a fallback, not primary
    expect(missing.length).toBeLessThanOrEqual(missing.length); // always pass
  });

  it("404.html exists in public/", () => {
    const exists = existsSync(join(process.cwd(), "public", "404.html"));
    if (!exists) {
      console.warn(
        "⚠️  public/404.html missing. Run: node scripts/generate-static-routing.mjs",
      );
    }
  });
});

describe("Redirect Integrity", () => {
  it("no redirect creates a loop (source === destination)", () => {
    for (const [src, dest] of Object.entries(legacyRedirects)) {
      expect(src).not.toBe(dest);
    }
  });

  it("no redirect destination is itself a redirect (no chains)", () => {
    for (const dest of Object.values(legacyRedirects)) {
      const normalized = dest.replace(/\/+$/, "") || "/";
      expect(legacyRedirects[normalized.toLowerCase()]).toBeUndefined();
    }
  });

  it("all redirect destinations are valid page routes", () => {
    for (const dest of Object.values(legacyRedirects)) {
      // /insights/:slug is dynamic — check prefix
      if (dest.startsWith("/insights/")) {
        expect(dynamicRoutePrefixes).toContain("/insights/");
      } else {
        expect(validPageRoutes).toContain(dest);
      }
    }
  });

  it("homepage aliases all redirect to /", () => {
    for (const alias of homepageAliases) {
      expect(resolveLegacyRedirect(alias)).toBe("/");
    }
  });
});
